  '+1', NULL, 'https://www.bill.com',
  COALESCE((SELECT id FROM categories WHERE slug='accounts-payable-software' LIMIT 1), @saas_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Jose', 'CA', 'San Jose, CA, US',
  'Intelligent financial automation for accounts payable, accounts receivable, and spend management in one platform.', 'BILL (formerly Bill.com) is a cloud-based financial operations platform serving small and midsize businesses across the US. It automates accounts payable and receivable workflows, expense management, and business payments. Founded in 2006, BILL went public on the NYSE in 2019 and has since expanded through acquisitions including Divvy and Invoice2go. Over 500,000 businesses and 8.3 million network members use BILL to manage their financial workflows.', 'https://www.google.com/s2/favicons?domain=bill.com&sz=256',
  2006, '500+', 'https://www.linkedin.com/company/bill', 'https://twitter.com/billcom', 'https://www.facebook.com/hq.bill',
  'company', 0, '["Accounts Payable","Accounts Receivable","Financial Automation","SMB Finance"]', '["Construction","Nonprofits","Education","Professional Services","Healthcare","Retail and Ecommerce","Hospitality","Technology"]', '["English"]', NULL, '[{"question":"What is BILL used for?","answer":"BILL is used to automate accounts payable and receivable processes, manage business expenses, control budgets, and send or receive payments - all from a single cloud platform."},{"question":"How many businesses use BILL?","answer":"Over 500,000 businesses and 8.3 million network members use BILL to manage their financial workflows as of 2026."},{"question":"Does BILL integrate with accounting software?","answer":"Yes, BILL integrates with QuickBooks, Xero, NetSuite, Sage Intacct, and other major accounting platforms to sync financial data automatically."},{"question":"Is BILL suitable for small businesses?","answer":"BILL is primarily designed for small and midsize businesses, helping them replace paper-based and spreadsheet-based financial processes with automated cloud workflows."},{"question":"When did BILL go public?","answer":"BILL Holdings, Inc. went public on the New York Stock Exchange in December 2019 and trades under the ticker symbol BILL."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  '[{"name":"Accounts Payable Automation","percentage":35},{"name":"Accounts Receivable / Invoicing","percentage":25},{"name":"Spend and Expense Management","percentage":20},{"name":"Business Payments Network","percentage":20}]', '[{"name":"SMB","percentage":75},{"name":"Mid-Market","percentage":20},{"name":"Enterprise","percentage":5}]', NULL, 'BILL serves over 500,000 businesses including accounting firms, suppliers, and multi-entity organizations across the US.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

