  'company', 0, '["Product Analytics","Digital Adoption","User Onboarding","In-App Guidance"]', '["Software and SaaS","Financial Services","Healthcare","Education","Government","Retail and E-commerce"]', '["English"]', '[{"name":"Deloitte Technology Fast 500","year":2023},{"name":"Fast Company Most Innovative Companies","year":2026}]', '[{"question":"What does Pendo do?","answer":"Pendo is a product experience platform that provides analytics on how users interact with software, delivers in-app guidance to drive adoption, and collects feedback to inform product roadmaps."},{"question":"Who uses Pendo?","answer":"Pendo is used by product, UX, and customer success teams at 14,000+ companies across industries including software, financial services, healthcare, and government."},{"question":"Does Pendo require code changes to implement?","answer":"Pendo uses a snippet-based installation that requires minimal code changes. In-app guides and analytics can be created and managed without ongoing engineering work."},{"question":"What is Pendo AI?","answer":"Pendo AI includes features such as Pendo Leo for predictive analytics, Agent Analytics for monitoring AI agents, and Sentiment for analyzing user feedback at scale."},{"question":"Where is Pendo headquartered?","answer":"Pendo is headquartered at 301 Hillsborough Street in Raleigh, North Carolina, with offices in 10 locations globally."}]',
