  '[{"name":"Product Analytics","percentage":35},{"name":"In-App Guides and Digital Adoption","percentage":30},{"name":"User Feedback and Sentiment","percentage":20},{"name":"Roadmapping and Prioritization","percentage":15}]', '[{"name":"SMB","percentage":20},{"name":"Mid-Market","percentage":35},{"name":"Enterprise","percentage":45}]', '[{"name":"Verizon","website":"https://www.verizon.com"},{"name":"Okta","website":"https://www.okta.com"},{"name":"Salesforce","website":"https://www.salesforce.com"}]', 'Pendo serves 14,000+ companies including Verizon, Morgan Stanley, LabCorp, Okta, Salesforce, OpenTable, and Zendesk.',
