  'company', 0, '["CRM Software","Sales Automation","Email Marketing","B2B Sales"]', '["Manufacturing","Construction","Marketing and Advertising","Professional Services","Technology","Real Estate"]', '["English"]', NULL, '[{"question":"Who is Nutshell CRM designed for?","answer":"Nutshell is built for small to mid-sized B2B organizations that want an easy-to-adopt CRM with built-in email marketing and sales automation - without needing a dedicated IT team."},{"question":"What features does Nutshell include?","answer":"Nutshell includes CRM, pipeline tracking, email marketing, sales automation, web chat, SMS, WhatsApp messaging, AI prospecting (Nutshell IQ), and proposals and invoicing."},{"question":"Where is Nutshell headquartered?","answer":"Nutshell is headquartered in Ann Arbor, Michigan, with additional offices in New York, Cape Town, and Sydney."},{"question":"How many businesses use Nutshell?","answer":"Nutshell supports over 5,000 businesses across 50 countries as of 2026."},{"question":"Does Nutshell integrate with other tools?","answer":"Yes, Nutshell integrates with Google Workspace, Microsoft 365, Slack, QuickBooks, Mailchimp, Zapier, and hundreds of other apps."}]',
