  UUID(), 'Brainhub', 'brainhub', 'Brainhub Team', 'info@brainhub.eu',
  '+48', NULL, 'https://brainhub.eu',
  COALESCE((SELECT id FROM categories WHERE slug='custom-software-development-companies' LIMIT 1), @it_sector), COALESCE((SELECT id FROM countries WHERE code='PL' LIMIT 1), @fallback_country), 'Gliwice', NULL, 'Gliwice, Poland',
  'High-performing teams of vetted software engineers solving complex technical problems.', 'Brainhub is a Polish software engineering company founded in 2015, headquartered in Gliwice, Poland, and acquired by STX Next in December 2024 to form a combined team of 600+ engineers. The company specializes in JavaScript/TypeScript-based web and mobile development, cloud solutions, AI development, and legacy modernization, serving clients across financial services, manufacturing, and media. Brainhub maintains a 4.9/5.0 Clutch rating across 53 verified reviews and has served clients including PwC, Credit Suisse, and National Geographic.', 'https://www.google.com/s2/favicons?domain=brainhub.eu&sz=256',
  2015, '51-200', 'https://www.linkedin.com/company/brainhub-pl', 'https://twitter.com/Brainhubeu', NULL,
  'company', 0, '["Software Engineering","Web Development","React","Node.js","Cloud Solutions"]', '["Financial Services","Manufacturing","Media","Healthcare","E-Commerce","Gaming"]', '["English","Polish"]', '[{"name":"Clutch Global Award - Top B2B Service Provider","year":2022}]', '[{"question":"What technologies does Brainhub specialize in?","answer":"Brainhub specializes in JavaScript and TypeScript ecosystems, including React, React Native, and Node.js, with cloud services on AWS (75%) and Azure (25%)."},{"question":"Is Brainhub still an independent company?","answer":"Brainhub was acquired by STX Next in December 2024, combining their expertise to form a 600+ engineer organization with expanded AI, Python, and data engineering capabilities."},{"question":"What types of clients does Brainhub work with?","answer":"Brainhub primarily serves midmarket companies (60% of business), with 20% from enterprise clients and 20% from small businesses, across 20+ industries."},{"question":"What is Brainhub''s minimum project size?","answer":"Brainhub''s minimum project size is $50,000+, with typical engagements involving dedicated team augmentation or full-cycle software delivery."}]',
  '$50,000+', '$50 - $99 / hr', NULL, NULL, '["GMT+01:00 (Berlin)"]',
  '[{"name":"Web Development","percentage":45},{"name":"Cloud Solutions & DevOps","percentage":35},{"name":"Enterprise App Modernization","percentage":20}]', '[{"name":"Midmarket ($10M - $1B)","percentage":60},{"name":"Enterprise (>$1B)","percentage":20},{"name":"Small Business (<$10M)","percentage":20}]', '[{"name":"PwC","website":"https://www.pwc.com"},{"name":"National Geographic","website":"https://www.nationalgeographic.com"}]', 'Brainhub has delivered software for PwC, Credit Suisse, National Geographic, Paradox Interactive, and Star Stable, among others.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- MindK (US - custom-software-development-companies)
