) SELECT
  UUID(), 'MindK', 'mindk', 'MindK Team', 'info@mindk.com',
  '+1', NULL, 'https://mindk.com',
  COALESCE((SELECT id FROM categories WHERE slug='custom-software-development-companies' LIMIT 1), @it_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'We empower businesses through technology - turning ideas into powerful digital solutions.', 'MindK is a custom software development company founded in 2009, with its registered US office in San Francisco and development roots in Ukraine, now operating distributed teams across Central and Eastern Europe. The company builds web and mobile applications, SaaS products, DevOps infrastructure, and provides team augmentation for startups and scale-ups, with 14+ years of experience and 170+ completed projects. MindK is an AWS Partner and was listed among Inc. 5000 Regionals: California 2021.', 'https://www.google.com/s2/favicons?domain=mindk.com&sz=256',
  2009, '51-200', 'https://www.linkedin.com/company/mindk', 'https://twitter.com/mindklab', NULL,
  'company', 0, '["Custom Software Development","Web & Mobile Apps","SaaS Development","DevOps","Team Augmentation"]', '["Healthcare","Education","HR & Recruitment","Media & Entertainment","Technology","E-Commerce"]', '["English","Ukrainian"]', '[{"name":"Inc. 5000 Regionals California","year":2021}]', '[{"question":"What does MindK build?","answer":"MindK builds custom web and mobile applications, SaaS platforms, MVP products, and provides DevOps consulting, UI/UX design, test automation, and team augmentation services."},{"question":"Where does MindK operate?","answer":"MindK has its US office in San Francisco, California, and development teams distributed across Ukraine, Czech Republic, and other Central and Eastern European locations."},{"question":"What industries does MindK serve?","answer":"MindK serves healthcare, education, HR and recruitment, media, and technology sectors, with notable clients including Adidas, Nokia, Paramount, and Roblox."},{"question":"What certifications does MindK hold?","answer":"MindK is an AWS certified partner and has been recognized on Inc. 5000 Regionals: California 2021 for rapid growth."},{"question":"What is MindK''s average Clutch rating?","answer":"MindK holds a 4.9/5.0 Clutch rating from 19 verified reviews, with 96% of clients recommending the agency."}]',
  '$25,000+', '$50 - $99 / hr', NULL, NULL, '["GMT-08:00 (Pacific)"]',
  '[{"name":"Custom Software Development","percentage":30},{"name":"Web Development","percentage":25},{"name":"Mobile App Development","percentage":15},{"name":"DevOps Managed Services","percentage":10},{"name":"IT Managed Services","percentage":10},{"name":"API Development & Modernization","percentage":10}]', '[{"name":"Midmarket ($10M - $1B)","percentage":55},{"name":"Small Business (<$10M)","percentage":30},{"name":"Enterprise (>$1B)","percentage":15}]', '[{"name":"Adidas","website":"https://www.adidas.com"},{"name":"Roblox","website":"https://www.roblox.com"},{"name":"Paramount","website":"https://www.paramount.com"}]', 'MindK has built software for Adidas, Nokia, Paramount, Roblox, H&M, Orkla, Electrolux, and Levels.fyi, across media, retail, and technology industries.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

