) SELECT
  UUID(), 'Trio', 'trio', 'Trio Team', 'info@trio.dev',
  '+55', NULL, 'https://trio.dev',
  COALESCE((SELECT id FROM categories WHERE slug='offshore-software-development-companies' LIMIT 1), @it_sector), COALESCE((SELECT id FROM countries WHERE code='BR' LIMIT 1), @fallback_country), 'Sao Paulo', NULL, 'Sao Paulo, Brazil',
  'Code that moves money. Talent that moves fast - nearshore software engineering for fintech.', 'Trio is a nearshore software engineering company founded in 2019, headquartered in Sao Paulo, Brazil, with founding roots in Boston, Massachusetts. The company connects fintech and high-growth technology companies with vetted software engineers from Latin America and Africa who operate in US timezones, specializing in IT staff augmentation, dedicated development teams, and fintech-focused software outsourcing. Trio maintains a 90% customer retention rate and has placed developers globally across payments, open banking, lending, and RegTech sectors.', 'https://www.google.com/s2/favicons?domain=trio.dev&sz=256',
  2019, '11-50', 'https://www.linkedin.com/company/triodev/', NULL, 'https://www.facebook.com/triodevelopers/',
  'company', 0, '["Nearshore Development","Fintech Engineering","Staff Augmentation","Dedicated Teams","Latin America"]', '["Financial Technology","Payments","Banking","RegTech","Insurance Tech","Technology"]', '["English","Portuguese"]', NULL, '[{"question":"What makes Trio different from other offshore companies?","answer":"Trio focuses exclusively on nearshore talent from Latin America and Africa, ensuring developers work in US timezones and integrate seamlessly into existing client teams."},{"question":"What industries does Trio serve?","answer":"Trio primarily serves fintech companies - including payments, open banking, lending, neobanks, core banking, RegTech, and fraud detection - and high-growth technology companies."},{"question":"Where are Trio''s developers located?","answer":"Trio sources engineers from Latin America (primarily Brazil and nearby countries) and Africa, all working in US-compatible timezones for seamless collaboration."},{"question":"What is Trio''s customer retention rate?","answer":"Trio maintains a 90% customer retention rate, reflecting the continuity and trust-based approach the company emphasizes over transactional outsourcing."}]',
  '$10,000+', '$50 - $99 / hr', NULL, NULL, '["GMT-05:00 (Eastern)"]',
  '[{"name":"IT Staff Augmentation","percentage":70},{"name":"Custom Software Development","percentage":10},{"name":"Mobile App Development","percentage":10},{"name":"Web Development","percentage":10}]', '[{"name":"Small Business (<$10M)","percentage":50},{"name":"Midmarket ($10M - $1B)","percentage":40},{"name":"Enterprise (>$1B)","percentage":10}]', NULL, 'Trio has served fintech and high-growth technology companies including Everyday Speech, helping them build and scale engineering teams with nearshore talent.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Arkenea (US - iphone-app-development-companies)
