) SELECT
  UUID(), 'Arkenea', 'arkenea', 'Arkenea Team', 'info@arkenea.com',
  '+1', NULL, 'https://arkenea.com',
  COALESCE((SELECT id FROM categories WHERE slug='iphone-app-development-companies' LIMIT 1), @it_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Cary', 'NC', 'Cary, NC, US',
  'We turn healthcare ideas into successful products - 100% dedicated to healthcare software for 15+ years.', 'Arkenea is a healthcare software development company founded in 2011, headquartered in Cary, North Carolina, with development teams in India and additional US offices in Florida. The company is exclusively dedicated to the healthcare sector, building HIPAA-compliant custom software, iOS and Android mobile apps, EHR systems, telemedicine platforms, and generative AI solutions for healthcare startups through Fortune 500 medical organizations. Arkenea has been recognized as Best Custom Healthcare Software Developer two years in a row.', 'https://www.google.com/s2/favicons?domain=arkenea.com&sz=256',
  2011, '51-200', 'https://www.linkedin.com/company/arkenea', NULL, NULL,
  'company', 0, '["Healthcare Software","iOS App Development","HIPAA Compliant","EHR Development","Telemedicine"]', '["Healthcare","Medical Devices","Telemedicine","Pharmaceuticals","Mental Health","Clinical Research"]', '["English"]', '[{"name":"Best Custom Healthcare Software Developer","year":2024}]', '[{"question":"What makes Arkenea unique in healthcare software?","answer":"Arkenea is 100% dedicated to healthcare technology - every project, engineer, and process is exclusively focused on HIPAA-compliant software for medical clients, from startups to Fortune 500 healthcare organizations."},{"question":"What types of healthcare software does Arkenea build?","answer":"Arkenea builds custom EHR/EMR systems, telemedicine platforms, mobile health apps (iOS and Android), prescription and pharmacy management software, patient management systems, and generative AI solutions for healthcare."},{"question":"Where is Arkenea headquartered?","answer":"Arkenea is headquartered at 2500 Regency Parkway, Cary, North Carolina, with additional offices in Florida and engineering teams in India."},{"question":"What awards has Arkenea received?","answer":"Arkenea has been recognized as Best Custom Healthcare Software Developer two years in a row and maintains a 4.9/5.0 Clutch rating with a 5.0 average referral rating."},{"question":"Who does Arkenea typically work with?","answer":"Arkenea works with healthcare startups, medical device companies, hospital systems, and Fortune 500 healthcare organizations seeking custom, HIPAA-compliant digital solutions."}]',
  '$50,000+', '$50 - $99 / hr', NULL, NULL, '["GMT-05:00 (Eastern)"]',
  '[{"name":"Mobile App Development (iOS & Android)","percentage":25},{"name":"Web Development","percentage":25},{"name":"Custom Healthcare Software","percentage":20},{"name":"AI & Generative AI Development","percentage":15},{"name":"API Development & Integration","percentage":10},{"name":"Application Management & Support","percentage":5}]', '[{"name":"Small Business (<$10M)","percentage":45},{"name":"Midmarket ($10M - $1B)","percentage":40},{"name":"Enterprise (>$1B)","percentage":15}]', NULL, 'Arkenea serves healthcare organizations including ORLink, TeleMedHome, NPHub, and Formulary Insights, building HIPAA-compliant software for clinical workflows and patient care.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

