-- Outschool (US - k-12-edtech-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Outschool', 'outschool', 'Outschool Team', 'info@outschool.com',
  '+1', NULL, 'https://www.outschool.com',
  COALESCE((SELECT id FROM categories WHERE slug='k-12-edtech-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'Live online classes for kids ages 3-18 across 140,000+ subjects taught by independent teachers.', 'Outschool is an online marketplace of live, small-group virtual classes for children ages 3 to 18. Founded in 2015 and launched in 2017, the platform connects learners with independent teachers across subjects ranging from arts and coding to math and social science. Outschool reached unicorn status in April 2021 at a $1.3 billion valuation and expanded to a $3 billion valuation by October 2021 after a $110 million Series D round led by Tiger Global. The company is backed by Y Combinator, Lightspeed Venture Partners, and Tiger Global Management.', 'https://www.google.com/s2/favicons?domain=outschool.com&sz=256',
  2015, '500+', 'https://www.linkedin.com/company/outschool', 'https://twitter.com/outschool', 'https://www.facebook.com/outschool',
  'company', 0, '["K-12 Education","Online Classes","EdTech","Kids Learning","Marketplace"]', '["K-12 Education","EdTech","Consumer Learning","After-School Programs"]', '["English"]', NULL, '[{"question":"What age range does Outschool serve?","answer":"Outschool offers classes for learners ages 3 through 18, covering preschool through high school."},{"question":"How are classes structured on Outschool?","answer":"Classes are live, small-group sessions taught by independent teachers via video conference. Formats include multi-day courses, one-time classes, and ongoing clubs."},{"question":"Who teaches on Outschool?","answer":"Outschool teachers are independent educators who apply to join the platform. They set their own curriculum, schedule, and pricing."},{"question":"Is Outschool a school replacement?","answer":"Outschool is designed for supplemental and enrichment learning rather than as a full-time school replacement, though homeschool families use it extensively."},{"question":"Where is Outschool based?","answer":"Outschool is headquartered in San Francisco, California, and was accepted into Y Combinator in 2015."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, '[{"name":"SMB","percentage":10},{"name":"Mid-Market","percentage":5},{"name":"Enterprise","percentage":5},{"name":"Consumer / Families","percentage":80}]', NULL, NULL,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Watershed (US - climate-tech-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Watershed', 'watershed', 'Watershed Team', 'info@watershed.com',
  '+1', NULL, 'https://www.watershed.com',
  COALESCE((SELECT id FROM categories WHERE slug='climate-tech-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'Enterprise sustainability platform combining climate science and AI to measure, report, and reduce carbon emissions.', 'Watershed is an enterprise software company founded in 2019 by former Stripe engineers Taylor Francis, Avi Itskovich, and Christian Anderson. The platform helps companies measure Scope 1, 2, and 3 emissions, prepare sustainability disclosures, engage their supply chains, and access verified carbon removal projects. Clients include Airbnb, Spotify, FedEx, and Visa. Watershed is backed by Sequoia Capital, Kleiner Perkins, and Greenoaks, and raised a $100 million Series B in 2022 led by Kleiner Perkins and Sequoia - their first co-investment since Google in 1999.', 'https://www.google.com/s2/favicons?domain=watershed.com&sz=256',
  2019, '500+', 'https://www.linkedin.com/company/watershedclimate', 'https://twitter.com/watershed', NULL,
  'company', 0, '["Carbon Accounting","ESG Reporting","Climate Tech","Sustainability AI","Emissions Reduction"]', '["Financial Services","Technology","Retail","Logistics","Consumer Goods","Private Equity"]', '["English"]', NULL, '[{"question":"What does Watershed measure?","answer":"Watershed measures Scope 1 (direct), Scope 2 (purchased energy), and Scope 3 (value chain) greenhouse gas emissions using its proprietary emissions model and integrations with enterprise data systems."},{"question":"What reporting standards does Watershed support?","answer":"Watershed supports GHG Protocol, CDP, TCFD, SEC climate disclosure, CSRD, and other major sustainability reporting frameworks."},{"question":"Who founded Watershed?","answer":"Watershed was founded in 2019 by Taylor Francis, Avi Itskovich, and Christian Anderson - three former Stripe employees who had previously worked on Stripe Climate."},{"question":"Does Watershed offer carbon offsets?","answer":"Yes. Watershed operates a curated marketplace of verified carbon removal and reduction projects, giving companies access to high-quality credits alongside its measurement and reporting tools."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, '[{"name":"Mid-Market","percentage":35},{"name":"Enterprise","percentage":65}]', '[{"name":"Airbnb","website":"https://www.airbnb.com"},{"name":"Spotify","website":"https://www.spotify.com"},{"name":"FedEx","website":"https://www.fedex.com"},{"name":"Visa","website":"https://www.visa.com"}]', 'Customers include Airbnb, Spotify, FedEx, Visa, and six of the top ten US private equity firms.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Solana Labs (US - layer-1-blockchain-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Solana Labs', 'solana-labs', 'Solana Labs Team', 'info@solanalabs.com',
  '+1', NULL, 'https://www.solanalabs.com',
  COALESCE((SELECT id FROM categories WHERE slug='layer-1-blockchain-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'Builder of the Solana blockchain ecosystem - a high-throughput Layer-1 network with sub-second finality and low transaction fees.', 'Solana Labs is the San Francisco-based technology company founded in 2018 by Anatoly Yakovenko and Raj Gokal that developed and launched the Solana blockchain. The Solana network went live in March 2020 and uses a novel Proof of History consensus mechanism to achieve high throughput and sub-second transaction finality. Beyond the core blockchain, Solana Labs operates Solana Mobile (maker of the Seeker web3 smartphone), runs an incubator for Web3 startups, and manages Solana Ventures. The SOL token reached an all-time high of $294 in January 2025.', 'https://www.google.com/s2/favicons?domain=solanalabs.com&sz=256',
  2018, '201-500', 'https://www.linkedin.com/company/solanalabs', 'https://twitter.com/solanalabs', NULL,
  'company', 0, '["Layer-1 Blockchain","Web3","DeFi","NFTs","Smart Contracts"]', '["Decentralized Finance","NFTs and Digital Assets","Web3 Gaming","Payments","Developer Tooling"]', '["English"]', NULL, '[{"question":"What is Solana Labs?","answer":"Solana Labs is the company that built and continues to develop the Solana blockchain, along with ecosystem products like Solana Mobile and the Solana Incubator for Web3 startups."},{"question":"When did the Solana network launch?","answer":"The Solana mainnet launched in March 2020, with the genesis block created on March 16, 2020."},{"question":"What makes Solana different from other blockchains?","answer":"Solana uses a Proof of History consensus mechanism that timestamps transactions before they are confirmed, enabling much higher throughput and lower fees than blockchains like Ethereum."},{"question":"What is Solana Mobile?","answer":"Solana Mobile is a subsidiary of Solana Labs that produces the Seeker smartphone - a dedicated Web3 mobile device with built-in crypto wallet functionality and dApp integration."},{"question":"Who are the founders of Solana Labs?","answer":"Solana Labs was co-founded by Anatoly Yakovenko, a former senior engineer at Qualcomm, and Raj Gokal in 2018 in San Francisco."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, NULL, NULL, NULL,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

