) SELECT
  UUID(), 'Rivian', 'rivian', 'Rivian Team', 'info@rivian.com',
  '+1', NULL, 'https://www.rivian.com',
  COALESCE((SELECT id FROM categories WHERE slug='electric-vehicle-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Irvine', 'CA', 'Irvine, CA, US',
  'American electric adventure vehicle maker producing the R1T pickup, R1S SUV, and commercial delivery vans - publicly traded on NASDAQ (RIVN).', 'Rivian Automotive is an American electric vehicle manufacturer founded in 2009 by R.J. Scaringe and headquartered in Irvine, California. The company produces the R1T electric pickup truck, R1S seven-passenger electric SUV, and a line of Electric Delivery Vans (EDVs) deployed at scale for Amazon. Rivian went public on NASDAQ in November 2021 under the ticker RIVN and has grown its headcount to approximately 17,000 employees as of mid-2026. Notable investors include Amazon (18.1% ownership), Volkswagen Group (16%), and Ford Motor Company.', 'https://www.google.com/s2/favicons?domain=rivian.com&sz=256',
  2009, '500+', 'https://www.linkedin.com/company/rivian', 'https://twitter.com/Rivian', NULL,
  'company', 0, '["Electric Vehicles","Adventure EVs","EV Pickup","Commercial EVs","NASDAQ: RIVN"]', '["Automotive","Last-Mile Delivery","Consumer Transportation","Fleet Management"]', '["English"]', NULL, '[{"question":"What vehicles does Rivian make?","answer":"Rivian produces the R1T electric pickup truck, R1S electric SUV, and a range of Electric Delivery Vans (EDVs) sold to commercial fleet operators including Amazon."},{"question":"Is Rivian publicly traded?","answer":"Yes. Rivian Automotive trades on the NASDAQ under the ticker symbol RIVN. The company went public in November 2021."},{"question":"Where does Rivian manufacture its vehicles?","answer":"Rivian''s primary manufacturing facility is in Normal, Illinois. The company is also constructing a second plant in Georgia."},{"question":"Who founded Rivian?","answer":"Rivian was founded in 2009 by R.J. Scaringe, who serves as the company''s CEO."},{"question":"What is Rivian''s relationship with Volkswagen?","answer":"Rivian and Volkswagen Group have a joint venture to develop next-generation software-defined vehicle technology, with Volkswagen investing up to $5 billion in the partnership."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, '[{"name":"Consumer / Individual Buyers","percentage":60},{"name":"Enterprise","percentage":40}]', '[{"name":"Amazon","website":"https://www.amazon.com"}]', 'Amazon is Rivian''s largest commercial client, deploying thousands of EDV electric delivery vans across its US logistics network.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Khan Academy (US - k-12-edtech-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Khan Academy', 'khan-academy', 'Khan Academy Team', 'info@khanacademy.org',
  '+1', NULL, 'https://www.khanacademy.org',
  COALESCE((SELECT id FROM categories WHERE slug='k-12-edtech-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Mountain View', 'CA', 'Mountain View, CA, US',
  'Free, world-class education for anyone, anywhere - a nonprofit offering personalized learning in math, science, and more for K-12 and beyond.', 'Khan Academy is a 501(c)(3) nonprofit educational organization founded in 2008 by Salman Khan and headquartered in Mountain View, California. The platform offers free instructional videos, practice exercises, and personalized learning dashboards covering K-12 math, sciences, history, literature, economics, and computer science. As of SY2024-25, Khan Academy has over 189 million registered users across 190 countries and is available in more than 50 languages. In 2023 the organization launched Khanmigo, an AI-powered tutoring assistant, which has since reached 2 million global users.', 'https://www.google.com/s2/favicons?domain=khanacademy.org&sz=256',
  2008, '201-500', 'https://www.linkedin.com/company/khan-academy', 'https://twitter.com/khanacademy', NULL,
  'company', 0, '["K-12 Education","Nonprofit","Free Learning","EdTech","AI Tutoring"]', '["K-12 Education","Higher Education","Homeschooling","Test Preparation"]', '["English","Spanish","French","Hindi","Portuguese","Arabic","Turkish"]', '[{"name":"Webby Award for Education","year":2012},{"name":"Princess of Asturias Award for International Cooperation","year":2019}]', '[{"question":"Is Khan Academy free?","answer":"Yes. Khan Academy is entirely free for learners. The nonprofit is funded through donations and grants from foundations and companies including the Gates Foundation and Google."},{"question":"Who founded Khan Academy?","answer":"Khan Academy was founded in 2008 by Salman ''Sal'' Khan, who originally created math tutoring videos for his cousins before expanding into a full nonprofit educational platform."},{"question":"What is Khanmigo?","answer":"Khanmigo is Khan Academy''s AI-powered tutoring and teaching assistant, launched in 2023. It uses a Socratic method to guide students rather than just giving answers, and reached 2 million global users by SY2024-25."},{"question":"What subjects does Khan Academy cover?","answer":"Khan Academy covers math from early childhood through calculus and beyond, plus science, computing, history, economics, test prep (SAT, GMAT, LSAT), and life skills."},{"question":"How many users does Khan Academy have?","answer":"Khan Academy has over 189 million registered users across 190 countries as of the 2024-25 academic year, with more than 30 million monthly active visitors."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, NULL, NULL, 'Major donors and supporters include the Bill and Melinda Gates Foundation and Google, which have provided significant grants to support Khan Academy''s global expansion.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Lucid Motors (US - electric-vehicle-startups)
