  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Lucid Motors', 'lucid-motors', 'Lucid Motors Team', 'info@lucidmotors.com',
  '+1', NULL, 'https://www.lucidmotors.com',
  COALESCE((SELECT id FROM categories WHERE slug='electric-vehicle-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Newark', 'CA', 'Newark, CA, US',
  'Luxury electric vehicle maker producing the Lucid Air sedan and Lucid Gravity SUV - publicly traded on NASDAQ (LCID).', 'Lucid Motors (formerly Atieva) is an American automotive and technology company founded in 2007, headquartered in Newark, California. Originally focused on battery technology and EV powertrains, the company rebranded as Lucid Motors in 2016 to pursue full vehicle manufacturing. Its flagship product, the Lucid Air, won the 2022 MotorTrend Car of the Year and holds the record for longest range of any production EV. Lucid is publicly traded on NASDAQ under the ticker LCID and is majority-owned by the Saudi Arabian Public Investment Fund (approximately 58%).', 'https://www.google.com/s2/favicons?domain=lucidmotors.com&sz=256',
  2007, '500+', 'https://www.linkedin.com/company/lucidmotors', 'https://twitter.com/LucidMotors', NULL,
  'company', 0, '["Luxury EVs","Electric Vehicles","EV Technology","NASDAQ: LCID","EV Powertrain"]', '["Automotive","Luxury Vehicles","EV Technology","Fleet Electrification"]', '["English"]', '[{"name":"MotorTrend Car of the Year (Lucid Air)","year":2022}]', '[{"question":"What vehicles does Lucid Motors make?","answer":"Lucid Motors produces the Lucid Air luxury electric sedan and the Lucid Gravity electric SUV. Additional midsize SUV models are in development."},{"question":"Is Lucid Motors publicly traded?","answer":"Yes. Lucid Group trades on NASDAQ under the ticker symbol LCID."},{"question":"Who is the largest shareholder of Lucid Motors?","answer":"The Public Investment Fund of Saudi Arabia is the largest shareholder, holding approximately 58% of Lucid Group as of 2024."},{"question":"What is Lucid''s range record?","answer":"The Lucid Air Grand Touring has an EPA-estimated range exceeding 500 miles on a single charge, making it one of the longest-range production EVs ever built."},{"question":"How is Lucid different from Tesla?","answer":"Lucid focuses on the ultra-premium luxury segment with a strong emphasis on powertrain efficiency and range. The company also sells EV powertrain systems to other automakers as a separate revenue line."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, '[{"name":"Consumer / Luxury Buyers","percentage":90},{"name":"Enterprise","percentage":10}]', NULL, NULL,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Maven (US - k-12-edtech-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Maven', 'maven', 'Maven Team', 'support@maven.com',
  '+1', NULL, 'https://www.maven.com',
  COALESCE((SELECT id FROM categories WHERE slug='k-12-edtech-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Austin', 'TX', 'Austin, TX, US',
  'Cohort-based course platform that lets domain experts teach live, interactive courses to professional and lifelong learners worldwide.', 'Maven is an online platform for cohort-based courses, founded in 2020 by Gagan Biyani (Udemy co-founder), Wes Kao (altMBA co-founder), and Shreyans Bhansali (Socratic co-founder, acquired by Google). The platform enables subject-matter experts to create and teach live, small-cohort courses primarily for professional and adult learners - covering AI, product management, engineering, design, and career development. Maven raised a $20 million Series A led by Andreessen Horowitz in 2021. Courses on the platform show a 96% week-over-week retention rate, compared to 16% for traditional MOOCs.', 'https://www.google.com/s2/favicons?domain=maven.com&sz=256',
  2020, '201-500', 'https://www.linkedin.com/company/maven-hq', 'https://twitter.com/mavenhq', NULL,
  'company', 0, '["Cohort-Based Courses","EdTech","Professional Learning","Expert Instruction","Live Online Courses"]', '["Professional Development","Technology Education","Business Education","Creative Skills","Career Advancement"]', '["English"]', NULL, '[{"question":"Who is Maven designed for?","answer":"Maven is designed for domain experts - professionals, executives, educators, and creators - who want to teach live, cohort-based courses to professional audiences."},{"question":"How is Maven different from other online course platforms?","answer":"Unlike self-paced MOOC platforms, Maven courses are live and cohort-based, meaning students go through the course together with structured interaction, community, and accountability - resulting in a 96% week-to-week retention rate."},{"question":"Who founded Maven?","answer":"Maven was co-founded in 2020 by Gagan Biyani (co-founder of Udemy), Wes Kao (co-founder of altMBA with Seth Godin), and Shreyans Bhansali (co-founder of Socratic, acquired by Google)."},{"question":"What topics are popular on Maven?","answer":"The most popular course topics on Maven include AI and machine learning, product management, software engineering, UX design, marketing, and career development for professionals."},{"question":"Has Maven raised funding?","answer":"Yes. Maven raised $20 million in a Series A round led by Andreessen Horowitz (a16z) in 2021, bringing its total funding to approximately $25.8 million."}]',
  NULL, NULL, NULL, NULL, '["GMT-06:00 (Central)"]',
  NULL, '[{"name":"SMB","percentage":20},{"name":"Mid-Market","percentage":30},{"name":"Consumer / Individual Professionals","percentage":50}]', NULL, NULL,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Pachama (US - climate-tech-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Pachama', 'pachama', 'Pachama Team', 'info@pachama.com',
  '+1', NULL, 'https://www.pachama.com',
  COALESCE((SELECT id FROM categories WHERE slug='climate-tech-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'San Francisco', 'CA', 'San Francisco, CA, US',
  'AI and satellite-powered forest carbon monitoring, verification, and marketplace - acquired by Carbon Direct in November 2025.', 'Pachama was a climate technology company founded in 2018 by Diego Saez Gil and Tomas Aftalion, headquartered in San Francisco, California. The company used satellite imagery, LiDAR, and artificial intelligence to measure carbon captured in forests, verify conservation projects, and power a carbon credit marketplace. Customers included Salesforce, Microsoft, Netflix, Shopify, and Airbnb. Pachama raised $79 million in total funding from investors including Serena Williams, Chris Sacca, and Social Capital before being acquired by Carbon Direct on November 10, 2025.', 'https://www.google.com/s2/favicons?domain=pachama.com&sz=256',
  2018, '51-200', 'https://www.linkedin.com/company/pachama', 'https://twitter.com/PachamaInc', NULL,
  'company', 0, '["Carbon Credits","Forest Conservation","Climate Tech","Remote Sensing","Carbon Markets"]', '["Carbon Markets","Corporate Sustainability","Forest Conservation","ESG Compliance"]', '["English"]', '[{"name":"Global Cleantech 100","year":2023}]', '[{"question":"What did Pachama do?","answer":"Pachama used satellite imagery, LiDAR, and AI to measure carbon stored in forests, verify conservation project claims, and operate a marketplace where companies could purchase verified forest carbon credits."},{"question":"Is Pachama still operating independently?","answer":"No. Pachama was acquired by Carbon Direct on November 10, 2025. Its technology and team, including co-founder Diego Saez Gil, are now part of Carbon Direct''s carbon management platform."},{"question":"Who founded Pachama?","answer":"Pachama was co-founded in 2018 by Diego Saez Gil (CEO) and Tomas Aftalion (CTO). Saez Gil previously founded WeHostels, a mobile travel booking app acquired by StudentUniverse."},{"question":"How much did Pachama raise before its acquisition?","answer":"Pachama raised approximately $79 million in total funding over multiple rounds from investors including Chris Sacca, Serena Williams, Social Capital, and Future Positive."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, '[{"name":"Mid-Market","percentage":40},{"name":"Enterprise","percentage":60}]', '[{"name":"Salesforce","website":"https://www.salesforce.com"},{"name":"Microsoft","website":"https://www.microsoft.com"},{"name":"Netflix","website":"https://www.netflix.com"},{"name":"Airbnb","website":"https://www.airbnb.com"}]', 'Clients included Salesforce, Microsoft, Netflix, Shopify, Airbnb, Workday, and Flexport before the company''s acquisition by Carbon Direct in November 2025.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Aptos (US - layer-1-blockchain-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
  category_id, country_id, city, state, hq_location, tagline, description, logo_url,
  founded_year, team_size, linkedin, twitter, facebook,
  listing_mode, is_hiring, header_tags, industries_served, languages, awards, faqs,
  min_project_size, hourly_rate, common_project_size, intro_video_url, timezones,
  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Aptos', 'aptos', 'Aptos Team', 'info@aptoslabs.com',
  '+1', NULL, 'https://www.aptoslabs.com',
  COALESCE((SELECT id FROM categories WHERE slug='layer-1-blockchain-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'Palo Alto', 'CA', 'Palo Alto, CA, US',
  'Layer-1 blockchain built for mass adoption - scalable, safe, and developer-friendly, using the Move programming language.', 'Aptos Labs is a Web3 technology company founded in 2021 by Mo Shaikh and Avery Ching, both former engineers on Meta''s Diem blockchain project. Headquartered in Palo Alto, California, Aptos Labs built the Aptos blockchain - a Layer-1 network that launched mainnet in October 2022, supporting parallel transaction execution and claiming a theoretical throughput of over 150,000 transactions per second. The company has raised $400 million across seed and Series A rounds from investors including Andreessen Horowitz, Apollo Global Management, Franklin Templeton, and Binance Labs. Products include Petra Wallet, Aptos Connect (keyless Web3 login), and Aptos Names on-chain identity.', 'https://www.google.com/s2/favicons?domain=aptoslabs.com&sz=256',
  2021, '201-500', 'https://www.linkedin.com/company/aptoslabs', 'https://twitter.com/AptosLabs', NULL,
  'company', 0, '["Layer-1 Blockchain","Web3","Move Language","DeFi","Smart Contracts"]', '["Decentralized Finance","NFTs and Digital Assets","Web3 Gaming","Payments","Enterprise Blockchain"]', '["English"]', NULL, '[{"question":"What is the Aptos blockchain?","answer":"Aptos is a Layer-1 blockchain that uses the Move programming language and parallel execution to achieve high throughput and low latency, targeting mainstream Web3 adoption."},{"question":"When did Aptos mainnet launch?","answer":"Aptos mainnet officially launched on October 18, 2022, with the genesis block created on October 12, 2022."},{"question":"Who founded Aptos Labs?","answer":"Aptos Labs was founded in 2021 by Mo Shaikh and Avery Ching, both of whom previously worked on Meta''s (Facebook''s) Diem blockchain before that project was cancelled."},{"question":"How much has Aptos Labs raised?","answer":"Aptos Labs raised $400 million - a $200 million seed round and a $200 million Series A - from investors including Andreessen Horowitz crypto fund, Apollo Global Management, Franklin Templeton, and Binance Labs."},{"question":"What is Aptos Connect?","answer":"Aptos Connect is a keyless Web3 wallet that lets users log in using familiar Web2 credentials (Google, Twitter, Facebook), eliminating the need to manage private keys or seed phrases."}]',
  NULL, NULL, NULL, NULL, '["GMT-08:00 (Pacific)"]',
  NULL, NULL, '[{"name":"Microsoft","website":"https://www.microsoft.com"}]', 'Aptos Labs has partnered with Microsoft to unlock Web3 on the Aptos Network, providing developers with AI-supported tools for effortless Web3 access.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- Polestar (SE - electric-vehicle-startups)
INSERT INTO submissions (
  uuid, company_name, slug, contact_name, email, phone_code, phone, website,
