  service_lines, focus_breakdown, client_logos, clients_summary,
  status, payment_status, plan_id, user_id, created_at, updated_at
) SELECT
  UUID(), 'Polestar', 'polestar', 'Polestar Team', 'info@polestar.com',
  '+46', NULL, 'https://www.polestar.com',
  COALESCE((SELECT id FROM categories WHERE slug='electric-vehicle-startups' LIMIT 1), @startup_sector), COALESCE((SELECT id FROM countries WHERE code='SE' LIMIT 1), @fallback_country), 'Torslanda', NULL, 'Torslanda, Sweden',
  'Swedish electric performance car brand producing premium EVs with uncompromising design - publicly traded on NASDAQ (PSNY).', 'Polestar is a Swedish electric vehicle manufacturer established as an independent brand in 2017 through a joint venture between Volvo Cars and Geely Holding. Headquartered in Torslanda, Sweden, the company produces premium electric cars including the Polestar 2, Polestar 3, and Polestar 4, with the Polestar 5 and Polestar 6 in development. Polestar operates an asset-light model, using manufacturing facilities owned by Volvo and Geely across Sweden, China, and the United States. Polestar went public on NASDAQ in June 2022 under the ticker PSNY, with ownership held by PSD Investment (44%), Geely Holding (22%), Volvo Cars (16%), and public shareholders (18%).', 'https://www.google.com/s2/favicons?domain=polestar.com&sz=256',
  2017, '500+', 'https://www.linkedin.com/company/polestarcars', 'https://twitter.com/PolestarCars', NULL,
  'company', 0, '["Electric Vehicles","Swedish EVs","Premium EVs","NASDAQ: PSNY","Performance Cars"]', '["Automotive","Luxury Vehicles","Consumer Transportation"]', '["English","Swedish"]', NULL, '[{"question":"What vehicles does Polestar make?","answer":"Polestar currently produces the Polestar 2 fastback, Polestar 3 large SUV, and Polestar 4 coupe SUV. The Polestar 5 performance sedan and Polestar 6 roadster are in development."},{"question":"Is Polestar publicly traded?","answer":"Yes. Polestar Automotive Holding UK PLC trades on NASDAQ under the ticker symbol PSNY. The company went public in June 2022."},{"question":"Who owns Polestar?","answer":"Polestar is owned by PSD Investment / Li Shufu (44%), Geely Holding (22%), Volvo Cars (16%), and public shareholders (18%)."},{"question":"Where is Polestar headquartered?","answer":"Polestar''s operational headquarters are in Torslanda, Sweden. The company''s legal headquarters are in Bristol, England, with a new Gothenburg, Sweden campus under construction."},{"question":"Where are Polestar vehicles manufactured?","answer":"Polestar uses an asset-light manufacturing model, producing vehicles at facilities owned by Volvo and Geely in China, and at the Volvo Cars plant in South Carolina, USA."}]',
  NULL, NULL, NULL, NULL, '["GMT+01:00 (Berlin)"]',
  NULL, '[{"name":"Consumer / Premium Buyers","percentage":100}]', NULL, NULL,
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

-- HOK (US - architects-2)
