  COALESCE((SELECT id FROM categories WHERE slug='architects-2' LIMIT 1), @ps_sector), COALESCE((SELECT id FROM countries WHERE code='US' LIMIT 1), @fallback_country), 'St. Louis', 'MO', 'St. Louis, MO, US',
  'A global design, architecture, engineering, and planning firm with 28 offices across three continents.', 'HOK was founded in 1955 by George Hellmuth, Gyo Obata, and George Kassabaum in St. Louis, Missouri. The firm is one of the largest architecture and design practices in North America, with approximately 1,800 professionals across 28 offices. HOK designs sports venues, airports, healthcare facilities, corporate campuses, and cultural institutions, including Mercedes-Benz Stadium in Atlanta and the National Air and Space Museum in Washington, D.C. The firm has been recognized by TIME Magazine as a Most Influential Company and by Fast Company as a Most Innovative Company.', 'https://www.google.com/s2/favicons?domain=hok.com&sz=256',
  1955, '500+', 'https://www.linkedin.com/company/hok', 'https://twitter.com/HOKNetwork', NULL,
  'company', 0, '["Architecture","Engineering","Interior Design","Urban Planning","Sustainable Design"]', '["Commercial Real Estate","Healthcare","Sports and Recreation","Aviation and Transportation","Education","Government","Hospitality","Science and Technology"]', '["English"]', '[{"name":"TIME 100 Most Influential Company","year":2022},{"name":"Fast Company Most Innovative Company","year":2024},{"name":"Metropolis Magazine Firm of the Year - Planet Positive Awards","year":2025},{"name":"AIA California Firm Award","year":2019}]', '[{"question":"What sectors does HOK specialize in?","answer":"HOK specializes in architecture and design for aviation, corporate, education, government, healthcare, hospitality, science and technology, sports and recreation, and mixed-use developments."},{"question":"How many offices does HOK have?","answer":"HOK operates 28 offices across North America, Europe, and Asia, including locations in London, Dubai, Hong Kong, and Mumbai."},{"question":"Is HOK committed to sustainable design?","answer":"Yes. HOK is a recognized leader in sustainable design - their Mercedes-Benz Stadium in Atlanta was the first LEED Platinum certified sports stadium in the U.S., and the firm has been named a Most Innovative Company by Fast Company for its sustainability work."},{"question":"What is HOK''s approach to project delivery?","answer":"HOK takes an integrated, collaborative approach, combining architecture, engineering, interior design, and planning under one roof to deliver holistic design solutions tailored to each client''s specific needs and goals."}]',
  '$50,000+', '$200 - $300 / hr', NULL, NULL, '["GMT-06:00 (Central)"]',
  '[{"name":"Architecture","percentage":50},{"name":"Interior Design","percentage":20},{"name":"Planning and Urban Design","percentage":15},{"name":"Engineering","percentage":10},{"name":"Landscape Architecture","percentage":5}]', '[{"name":"Enterprise (>$1B)","percentage":70},{"name":"Midmarket ($10M - $1B)","percentage":25},{"name":"Small Business (<$10M)","percentage":5}]', '[{"name":"Mercedes-Benz","website":"https://www.mercedes-benz.com"},{"name":"Apple","website":"https://www.apple.com"},{"name":"Google","website":"https://www.google.com"},{"name":"Stanford University","website":"https://www.stanford.edu"}]', 'HOK''s clients include major corporations such as Apple, Microsoft, Google, and Mercedes-Benz, as well as universities and government agencies globally.',
  'pending', 'unpaid', @free_plan, NULL, NOW(), NOW();

